}

private Dictionary<string, object> GetRequestBodyDictionary(HttpContext context)
{
    if (_cachedBodyDictionary != null)
        return _cachedBodyDictionary;

    string strBody = ReadRequestBody(context);
    if (String.IsNullOrEmpty(strBody))
    {
        _cachedBodyDictionary = new Dictionary<string, object>();
        return _cachedBodyDictionary;
    }

    JavaScriptSerializer objSerializer = new JavaScriptSerializer();
    _cachedBodyDictionary = objSerializer.Deserialize<Dictionary<string, object>>(strBody);
    if (_cachedBodyDictionary == null)
        _cachedBodyDictionary = new Dictionary<string, object>();
    return _cachedBodyDictionary;
}

private string ReadRequestBody(HttpContext context)
{
    if (_cachedRequestBody != null)
        return _cachedRequestBody;

    if (context.Request.InputStream == null)
    {
        _cachedRequestBody = "";
        return _cachedRequestBody;
    }

    if (context.Request.InputStream.CanSeek)
        context.Request.InputStream.Position = 0;

    StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
    _cachedRequestBody = objReader.ReadToEnd();
    return _cachedRequestBody;
}

