/* Training Quantity Dashboard - scope tqd-dash */

.page-wrapper .page-content .tqd-dash-btn-outline {
    border-radius: 8px;
    font-size: 0.85rem;
    padding: 0.45rem 1rem;
}

.page-wrapper .page-content .tqd-dash-state .alert {
    border-radius: 10px;
}

.page-wrapper .page-content .tqd-dash-filter-actions {
    margin-top: 0.25rem;
}

.page-wrapper .page-content .tqd-filter-card {
    position: relative;
    z-index: 20;
    overflow: visible !important;
}

.page-wrapper .page-content .tqd-filter-card .form-label {
    color: #334155;
    font-size: 0.82rem;
    font-weight: 600;
    margin-bottom: 0.4rem;
}

.page-wrapper .page-content .tqd-dash-chart-empty {
    min-height: 280px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--sch-text-muted, #6c7a89);
    font-size: 0.9rem;
}

.page-wrapper .page-content .tqd-dash-chart-scroll-wrap {
    width: 100%;
    overflow-y: auto;
    overflow-x: hidden;
    padding-right: 0.25rem;
}

/* Multi-select */
.page-wrapper .page-content .tqd-ms {
    position: relative;
}

.page-wrapper .page-content .tqd-ms-trigger {
    align-items: center;
    background-color: #fff;
    border: 1px solid #d8e0ea;
    border-radius: 0.375rem;
    color: #334155;
    display: flex;
    min-height: 38px;
    overflow: hidden;
    padding: 0.375rem 2.2rem 0.375rem 0.75rem;
    position: relative;
    text-align: left;
    width: 100%;
}

.page-wrapper .page-content .tqd-ms-trigger::after {
    border-bottom: 0;
    border-left: 0.3em solid transparent;
    border-right: 0.3em solid transparent;
    border-top: 0.3em solid;
    content: "";
    position: absolute;
    right: 0.8rem;
    top: 50%;
    transform: translateY(-50%);
}

.page-wrapper .page-content .tqd-ms-label {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.page-wrapper .page-content .tqd-ms-count {
    align-items: center;
    background: #e8efff;
    border-radius: 999px;
    color: #0d2a6b;
    display: inline-flex;
    font-size: 0.7rem;
    font-weight: 700;
    justify-content: center;
    margin-left: 0.45rem;
    min-width: 1.35rem;
    padding: 0.1rem 0.35rem;
}

.page-wrapper .page-content .tqd-ms-menu {
    background: #fff;
    border: 1px solid #cbd5e1;
    border-radius: 0.5rem;
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.16);
    display: none;
    left: 0;
    max-height: 300px;
    min-width: 100%;
    overflow-y: auto;
    padding: 0.45rem;
    position: absolute;
    right: 0;
    top: calc(100% + 4px);
    z-index: 1080;
}

.page-wrapper .page-content .tqd-ms.open .tqd-ms-menu {
    display: block;
}

.page-wrapper .page-content .tqd-ms-item {
    align-items: flex-start;
    border-radius: 0.35rem;
    cursor: pointer;
    display: flex;
    font-size: 0.82rem;
    gap: 0.45rem;
    line-height: 1.3;
    margin: 0;
    padding: 0.45rem 0.5rem;
}

.page-wrapper .page-content .tqd-ms-item:hover {
    background: #eff6ff;
    color: #0d2a6b;
}

.page-wrapper .page-content .tqd-ms-item input {
    flex: 0 0 auto;
    margin-top: 0.12rem;
}

.page-wrapper .page-content .tqd-ms-divider {
    border-top: 1px solid #e5e7eb;
    margin: 0.25rem 0;
}

.page-wrapper .page-content .tqd-ms-empty {
    color: #64748b;
    font-size: 0.8rem;
    padding: 0.65rem;
    text-align: center;
}

/* KPI stat box - pill style (đồng bộ sĩ số / tốt nghiệp) */
.page-wrapper .page-content .tqd-dash-kpi-card {
    padding: 1.25rem 1.35rem;
    height: 100%;
    border-radius: 10px;
    border: none;
    box-shadow: 0 4px 12px rgba(0, 45, 94, 0.06);
}

.page-wrapper .page-content .tqd-dash-kpi-card:hover {
    transform: none;
    box-shadow: 0 6px 16px rgba(0, 45, 94, 0.1);
}

.page-wrapper .page-content .tqd-dash-kpi-inner {
    gap: 0.75rem;
}

.page-wrapper .page-content .tqd-dash-kpi-main {
    min-width: 0;
    flex: 1;
}

.page-wrapper .page-content .tqd-dash-kpi-head {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.65rem;
}

.page-wrapper .page-content .tqd-dash-kpi-head-icon {
    font-size: 1rem;
    color: #002d5e;
    flex-shrink: 0;
    line-height: 1;
}

.page-wrapper .page-content .tqd-dash-kpi-title {
    font-size: 0.72rem;
    font-weight: 700;
    color: #002d5e;
    text-transform: uppercase;
    letter-spacing: 0.02em;
    line-height: 1.3;
}

.page-wrapper .page-content .tqd-dash-kpi-pill {
    display: inline-block;
    background-color: #e8efff;
    border-radius: 50px;
    padding: 0.35rem 1rem;
    min-width: 56px;
    text-align: center;
}

.page-wrapper .page-content .tqd-dash-kpi-card .sch-dash-kpi-value {
    font-size: 1.1rem;
    font-weight: 700;
    color: #002d5e;
    line-height: 1.2;
}

.page-wrapper .page-content .tqd-dash-kpi-deco {
    width: 44px;
    height: 44px;
    border: 1px dashed #3b82f6;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    color: #002d5e;
    font-size: 1.05rem;
}

.page-wrapper .page-content .tqd-dash-kpi-teal .tqd-dash-kpi-head-icon,
.page-wrapper .page-content .tqd-dash-kpi-teal .tqd-dash-kpi-title,
.page-wrapper .page-content .tqd-dash-kpi-teal .sch-dash-kpi-value {
    color: #0f766e;
}

.page-wrapper .page-content .tqd-dash-kpi-teal .tqd-dash-kpi-pill {
    background-color: rgba(26, 188, 156, 0.22);
}

.page-wrapper .page-content .tqd-dash-kpi-teal .tqd-dash-kpi-deco {
    border-color: #1abc9c;
    color: #1abc9c;
}

.page-wrapper .page-content .tqd-dash-kpi-blue .tqd-dash-kpi-head-icon,
.page-wrapper .page-content .tqd-dash-kpi-blue .tqd-dash-kpi-title,
.page-wrapper .page-content .tqd-dash-kpi-blue .sch-dash-kpi-value {
    color: #1d4ed8;
}

.page-wrapper .page-content .tqd-dash-kpi-blue .tqd-dash-kpi-pill {
    background-color: rgba(52, 152, 219, 0.22);
}

.page-wrapper .page-content .tqd-dash-kpi-blue .tqd-dash-kpi-deco {
    border-color: #3498db;
    color: #3498db;
}

.page-wrapper .page-content .tqd-dash-kpi-orange .tqd-dash-kpi-head-icon,
.page-wrapper .page-content .tqd-dash-kpi-orange .tqd-dash-kpi-title,
.page-wrapper .page-content .tqd-dash-kpi-orange .sch-dash-kpi-value {
    color: #c2410c;
}

.page-wrapper .page-content .tqd-dash-kpi-orange .tqd-dash-kpi-pill {
    background-color: rgba(230, 126, 34, 0.22);
}

.page-wrapper .page-content .tqd-dash-kpi-orange .tqd-dash-kpi-deco {
    border-color: #e67e22;
    color: #e67e22;
}

.page-wrapper .page-content .tqd-dash-kpi-yellow .tqd-dash-kpi-head-icon,
.page-wrapper .page-content .tqd-dash-kpi-yellow .tqd-dash-kpi-title,
.page-wrapper .page-content .tqd-dash-kpi-yellow .sch-dash-kpi-value {
    color: #a16207;
}

.page-wrapper .page-content .tqd-dash-kpi-yellow .tqd-dash-kpi-pill {
    background-color: rgba(212, 161, 6, 0.24);
}

.page-wrapper .page-content .tqd-dash-kpi-yellow .tqd-dash-kpi-deco {
    border-color: #d4a106;
    color: #d4a106;
}

/* Table */
.page-wrapper .page-content .tqd-table-wrap {
    max-height: 680px;
    overflow: auto;
}

.page-wrapper .page-content #tqdDetailTable {
    font-size: 0.77rem;
    min-width: 1500px;
}

.page-wrapper .page-content #tqdDetailTable thead th {
    background: #eff6ff;
