    if (chartEl) chartEl.style.display = isEmpty ? "none" : "";
    if (emptyEl) emptyEl.className = isEmpty ? "tqd-dash-chart-empty" : "tqd-dash-chart-empty d-none";
}

function renderApex(key, elId, emptyId, options) {
    destroyChart(key);
    var el = byId(elId);
    if (!el || typeof ApexCharts === "undefined") return;
    if (!options || options.isEmpty) {
        el.innerHTML = "";
        setChartEmpty(elId, emptyId, true);
        return;
    }
    setChartEmpty(elId, emptyId, false);
    if (window.DashboardChartUtils) {
        window.DashboardChartUtils.enhanceBarDataLabels(options);
    }
    charts[key] = new ApexCharts(el, options);
