// SỐ LƯỢNG ĐÀO TẠO (*_Total) -> ĐÃ ĐÀO TẠO (*2) -> ĐANG ĐÀO TẠO (*1)
var metricFields = [
    "SiSo_Total", "DanSu_Total", "BoDoi_Total", "DanToc_Total",
    "SiSo2", "DanSu2", "BoDoi2", "DanToc2",
    "SiSo1", "DanSu1", "BoDoi1", "DanToc1"
];
function sumRows(rows) {
    var result = {};
    metricFields.forEach(function (field) { result[field] = 0; });
    rows.forEach(function (row) {
        metricFields.forEach(function (field) { result[field] += number(row[field]); });
    });
    return result;
}
function metricCells(values) {
    return metricFields.map(function (field) {
        return '<td class="tqd-num">' + formatNumber(values[field]) + "</td>";
    }).join("");
}
function infoCells(code, title, sticky) {
    var stickyClass = sticky ? " tqd-sticky-col" : "";
    return ''
        + '<td class="tqd-col-code' + stickyClass + '">' + escapeHtml(code || "") + "</td>"
        + '<td class="tqd-col-name' + stickyClass + '">' + escapeHtml(title || "") + "</td>";
}
function groupRows(rows) {
    var levels = [], levelMap = {};
    rows.forEach(function (row) {
        var levelKey = String(row.TrainingLevelID || "");
        var branchKey = String(row.SpecialBranchID || "");
        if (!levelMap[levelKey]) {
            levelMap[levelKey] = {
                code: row.TrainingLevelID || "",
                name: row.TrainingLevelName || "Chưa xác định",
                rows: [],
                branches: [],
                branchMap: {}
            };
            levels.push(levelMap[levelKey]);
        }
        var level = levelMap[levelKey];
        level.rows.push(row);
        if (!level.branchMap[branchKey]) {
            level.branchMap[branchKey] = {
                code: row.SpecialBranchID || "",
                name: row.SpecialBranchName || "Chưa xác định",
                rows: []
            };
            level.branches.push(level.branchMap[branchKey]);
        }
        level.branchMap[branchKey].rows.push(row);
    });
    return levels;
}
function renderTable(rows, summary) {
    var html = "";
    groupRows(rows).forEach(function (level) {
        html += '<tr class="tqd-group-level">'
