            + "</tr>";
        level.branches.forEach(function (branch) {
            html += '<tr class="tqd-group-branch">'
                + infoCells(branch.code, branch.name, false)
                + metricCells(sumRows(branch.rows))
                + "</tr>";
            branch.rows.forEach(function (row) {
