                    + "</tr>";
            });
        });
    });
    var totalValues = {
        SiSo_Total: summary.total, DanSu_Total: summary.civilian, BoDoi_Total: summary.military, DanToc_Total: summary.ethnic,
        SiSo2: summary.graduated, DanSu2: summary.graduatedCivilian, BoDoi2: summary.graduatedMilitary, DanToc2: summary.graduatedEthnic,
        SiSo1: summary.studying, DanSu1: summary.studyingCivilian, BoDoi1: summary.studyingMilitary, DanToc1: summary.studyingEthnic
    };
    html += '<tr class="tqd-grand-total">'
