    var topBranches = branches.slice().sort(function (a, b) {
        return number(b.total) - number(a.total);
    }).slice(0, 15);
    var branchOptions = {
        isEmpty: topBranches.length === 0,
        series: [
            { name: "Đang học", data: topBranches.map(function (x) { return number(x.studying); }) },
            { name: "Đã tốt nghiệp", data: topBranches.map(function (x) { return number(x.graduated); }) }
        ],
        chart: Object.assign({
            type: "bar",
            height: Math.max(360, topBranches.length * 36),
            stacked: true
        }, baseChartOpts),
        plotOptions: {
            bar: { horizontal: true, borderRadius: 6, barHeight: "68%" }
        },
        colors: [SUCCESS, PRIMARY],
        dataLabels: {
            enabled: true,
            style: { colors: ["#fff"], fontSize: "11px", fontWeight: 600 }
        },
        xaxis: {
            categories: topBranches.map(function (x) { return x.specialBranchName; }),
            labels: { formatter: formatNumber, style: { fontSize: "11px" } }
        },
        yaxis: {
            labels: { maxWidth: 180, style: { fontSize: "11px" } }
        },
        grid: { strokeDashArray: 4, borderColor: "#e2e8f0", padding: { right: 8 } },
        legend: { position: "top", fontFamily: TITLE_FONT },
        tooltip: {
            y: { formatter: function (val) { return formatNumber(val) + " HSSV"; } }
        }
    };
    renderApex("branch", "tqdChartBySpecialBranch", "tqdChartBySpecialBranchEmpty", branchOptions);

    var topCourses = aggregateByCourse(rows).slice(0, 12);
    var courseOptions = {
        isEmpty: topCourses.length === 0,
        series: [
            { name: "Đang học", data: topCourses.map(function (x) { return number(x.studying); }) },
            { name: "Đã tốt nghiệp", data: topCourses.map(function (x) { return number(x.graduated); }) }
        ],
        chart: Object.assign({
            type: "bar",
            height: Math.max(360, topCourses.length * 36),
            stacked: true
        }, baseChartOpts),
        plotOptions: {
            bar: { horizontal: true, borderRadius: 6, barHeight: "68%" }
        },
        colors: [SUCCESS, PRIMARY],
        dataLabels: {
            enabled: true,
            style: { colors: ["#fff"], fontSize: "11px", fontWeight: 600 }
        },
        xaxis: {
            categories: topCourses.map(function (x) { return x.courseName; }),
            labels: { formatter: formatNumber, style: { fontSize: "11px" } }
        },
        yaxis: {
            labels: { maxWidth: 160, style: { fontSize: "11px" } }
        },
        grid: { strokeDashArray: 4, borderColor: "#e2e8f0", padding: { right: 8 } },
        legend: { position: "top", fontFamily: TITLE_FONT },
        tooltip: {
            y: { formatter: function (val) { return formatNumber(val) + " HSSV"; } }
        }
    };
    renderApex("course", "tqdChartByCourse", "tqdChartByCourseEmpty", courseOptions);
}

function resetFilters() {
    if (!filterData) return;
    renderMultiSelect("tqdScienceFilter", filterData.sciences);
    renderMultiSelect("tqdCourseFilter", filterData.courses);
    renderMultiSelect("tqdTrainingLevelFilter", filterData.trainingLevels);
    renderSingleSelect("tqdTrainingTypeFilter", filterData.trainingTypes, "Tất cả loại hình");
    renderSingleSelect("tqdBranchFilter", filterData.branches, "Tất cả ngành");
    renderMultiSelect("tqdSpecialBranchFilter", filterData.specialBranches);
    byId("tqdFromDate").value = "";
    byId("tqdToDate").value = "";
    filterSpecialBranches();
    loadData();
}

function bindEvents() {
    document.addEventListener("click", function () { closeMultiSelects(null); });
    byId("tqdDashBtnLoad").addEventListener("click", loadData);
    byId("tqdDashBtnReset").addEventListener("click", resetFilters);
    byId("tqdBranchFilter").addEventListener("change", filterSpecialBranches);
    byId("tqdDashBtnToggleFilter").addEventListener("click", function () {
        var body = byId("tqdDashFilterBody");
        var hidden = body.classList.toggle("d-none");
        this.setAttribute("aria-expanded", hidden ? "false" : "true");
        this.querySelector("i").className = hidden ? "bi bi-chevron-down" : "bi bi-chevron-up";
    });
}

